# 群的乘法表
elements = ['e', 'a', 'h', 'b', 'g', 'z', 'eps', 'd']  # e,α,η,β,γ,ζ,ε,δ

# 乘法表 (行*列)
table = {
    'e':   {'e':'e', 'a':'a', 'h':'h', 'b':'b', 'g':'g', 'z':'z', 'eps':'eps', 'd':'d'},
    'a':   {'e':'a', 'a':'h', 'h':'b', 'b':'e', 'g':'z', 'z':'eps', 'eps':'d', 'd':'g'},
    'h':   {'e':'h', 'a':'b', 'h':'e', 'b':'a', 'g':'eps', 'z':'d', 'eps':'g', 'd':'z'},
    'b':   {'e':'b', 'a':'e', 'h':'a', 'b':'h', 'g':'d', 'z':'g', 'eps':'z', 'd':'eps'},
    'g':   {'e':'g', 'a':'z', 'h':'eps', 'b':'d', 'g':'e', 'z':'a', 'eps':'h', 'b':'b'},
    'z':   {'e':'z', 'a':'eps', 'h':'d', 'b':'g', 'g':'a', 'z':'h', 'eps':'b', 'd':'e'},
    'eps': {'e':'eps', 'a':'d', 'h':'g', 'b':'z', 'g':'h', 'z':'b', 'eps':'e', 'd':'a'},
    'd':   {'e':'d', 'a':'g', 'h':'z', 'b':'eps', 'g':'b', 'z':'e', 'eps':'a', 'd':'h'},
}

# 1. 检查群是否交换
print("=== 检查交换性 ===")
abelian = True
for x in elements:
    for y in elements:
        if table[x][y] != table[y][x]:
            abelian = False
            print(f"  {x}*{y} = {table[x][y]} != {y}*{x} = {table[y][x]}")
if abelian:
    print("  群是交换群（Abelian群）")

# 2. 求每个元素的逆元
print("\n=== 求逆元 ===")
inv = {}
for x in elements:
    for y in elements:
        if table[x][y] == 'e':
            inv[x] = y
            print(f"  {x}^(-1) = {y}")
            break

# 3. H = {e, g} (即 {e, γ})
H = {'e', 'g'}
print(f"\n=== H = {{e, γ}} ===")

# 4. 对每个 g_elem in G, 计算 gHg^{-1}
print("\n=== 计算 gHg^{-1} ===")
all_normal = True
for g_elem in elements:
    conj = set()
    for h_elem in H:
        # g * h * g^{-1}
        gh = table[g_elem][h_elem]
        ghg_inv = table[gh][inv[g_elem]]
        conj.add(ghg_inv)
    is_H = (conj == H)
    if not is_H:
        all_normal = False
    print(f"  {g_elem} H {g_elem}^(-1) = {conj}  {'= H ✓' if is_H else '≠ H ✗'}")

print(f"\n=== 结论 ===")
if all_normal:
    print("H 是 G 的正规子群")
else:
    print("H 不是 G 的正规子群")

# 5. 额外：识别群的结构
print("\n=== 群结构分析 ===")
# 求每个元素的阶
for x in elements:
    order = 1
    current = x
    while current != 'e':
        current = table[current][x]
        order += 1
    print(f"  ord({x}) = {order}")
